script:
frappe.ui.form.on('RFQ Comparison Sheet', {
	refresh: function(frm) {
		frm.fields_dict['items'].grid.update_docfield_property('supplier', 'formatter', function(value) {
			return `<div style="overflow:hidden; text-overflow:ellipsis; white-space:nowrap; max-width:200px;" title="${value || ''}">${value || ''}</div>`;
		});
		['price_score', 'lead_time_score', 'weighted_mark'].forEach(function(fieldname) {
			frm.fields_dict['items'].grid.update_docfield_property(fieldname, 'formatter', function(value) {
				if (value === null || value === undefined) return '';
				return parseFloat(value).toFixed(2);
			});
		});

		setTimeout(function() {
			frm.fields_dict['items'].grid.refresh();
		}, 300);

		if (!frm.doc.__islocal && frm.doc.request_for_quotation) {
			frm.add_custom_button(__('By Proposal Comparison'), function() {
				frappe.set_route('query-report', 'RFQ Comparison - By Proposal', {rfq: frm.doc.request_for_quotation});
			}, __('View'));
		}
	}
});

frappe.ui.form.on('Request for Quotation', {
	refresh: function(frm) {
		if (frm.doc.workflow_state === 'Approved') {
			frappe.call({
				method: 'proc_portal.api.rfqs.get_comparison_sheet_status',
				args: { rfq_name: frm.doc.name },
				callback: function(r) {
					if (!r.message) return;
					var status = r.message;

					if (!status.exists) {
						frm.add_custom_button('Generate Comparison Sheet', function() {
							frappe.call({
								method: 'proc_app.api.rfq.generate_comparison_sheet',
								args: { rfq_name: frm.doc.name },
								freeze: true,
								freeze_message: __('Generating comparison sheet...'),
								callback: function(gen_r) {
									if (gen_r.message) {
										frappe.set_route('rfq-comparison', gen_r.message);
									}
								}
							});
						}, __('Create'));
						return;
					}

					if (!status.is_approved) {
						frm.add_custom_button('Regenerate Comparison Sheet', function() {
							frappe.call({
								method: 'proc_app.api.rfq.generate_comparison_sheet',
								args: { rfq_name: frm.doc.name },
								freeze: true,
								freeze_message: __('Regenerating comparison sheet...'),
								callback: function(gen_r) {
									if (gen_r.message) {
										frappe.set_route('rfq-comparison', gen_r.message);
									}
								}
							});
						}, __('Create'));
					}

					frm.add_custom_button('View Comparison Sheet', function() {
						frappe.set_route('rfq-comparison', status.name);
					}, __('View'));

					frappe.call({
						method: 'proc_portal.api.rfqs.get_purchase_orders_for_rfq',
						args: { rfq_name: frm.doc.name },
						callback: function(po_r) {
							var existing_pos = po_r.message || [];
							if (existing_pos.length) {
								frm.add_custom_button('View Purchase Orders', function() {
									frappe.set_route('List', 'Purchase Order', {
										name: ['in', existing_pos.map(function(po) { return po.name; })]
									});
								}, __('View'));
							} else {
								frm.add_custom_button('Generate Purchase Orders', function() {
									frappe.call({
										method: 'proc_app.api.rfq.generate_purchase_orders_from_comparison',
										args: { rfq_name: frm.doc.name },
										freeze: true,
										freeze_message: __('Generating purchase orders...'),
										callback: function(r) {
											if (r.message) {
												frappe.msgprint(__('Created: ') + r.message.join(', '));
											}
										}
									});
								}, __('Create'));
							}
						}
					});
				}
			});
		}
	}
});

frappe.ui.form.on('Supplier Quotation Item', {
	lead_time_days: function(frm, cdt, cdn) {
		let row = locals[cdt][cdn];
		if (row.lead_time_days) {
			let base_date = frm.doc.transaction_date || frappe.datetime.get_today();
			row.expected_delivery_date = frappe.datetime.add_days(base_date, row.lead_time_days);
			frm.refresh_field('items');
		}
	}
});

frappe.ui.form.on('Supplier ASN', {
	refresh: function(frm) {
		if (frm.doc.docstatus !== 2 && frm.doc.status !== 'Cancelled') {
			frm.add_custom_button('Purchase Receipt', function() {
				frappe.model.open_mapped_doc({
					method: 'proc_app.api.asn.make_purchase_receipt_from_asn',
					frm: frm,
				});
			}, __('Create'));
		}
	}
});

frappe.ui.form.on('Contract', {
	refresh: function(frm) {
		if (frm.doc.__islocal) return;

		// Consumption indicator - only meaningful when a value is set
		if (frm.doc.contract_value) {
			frappe.call({
				method: 'proc_portal.api.contracts.get_contract_consumption',
				args: { contract_name: frm.doc.name },
				callback: function(r) {
					if (!r.message) return;
					const d = r.message;
					const color = d.over_committed ? 'red' : (d.consumed_pct >= 80 ? 'orange' : 'blue');
					frm.dashboard.add_indicator(
						__('Consumed: {0}% ({1} of {2})', [d.consumed_pct, format_currency(d.consumed), format_currency(d.contract_value)]),
						color
					);
					if (d.remaining) {
						frm.dashboard.add_indicator(__('Remaining: {0}', [format_currency(d.remaining)]), 'green');
					}
				}
			});
		}

		// Renew - gated by can_renew_contract() (Approved + within 90 days of
		// expiry, or already past it), the same rule both the portal and desk
		// enforce and the server itself re-checks in renew_contract().
		frappe.call({
			method: 'proc_portal.api.contracts.can_renew_contract',
			args: { contract_name: frm.doc.name },
			callback: function(r) {
				if (!r.message || !r.message.can_renew) return;
				frm.add_custom_button(__('Renew Contract'), function() {
					const dialog = new frappe.ui.Dialog({
						title: __('Renew Contract'),
						fields: [
							{fieldname: 'new_start_date', label: __('New Start Date'), fieldtype: 'Date', reqd: 1},
							{fieldname: 'new_end_date', label: __('New End Date'), fieldtype: 'Date', reqd: 1},
							{fieldname: 'new_value', label: __('New Contract Value'), fieldtype: 'Currency', default: frm.doc.contract_value},
						],
						primary_action_label: __('Renew'),
						primary_action: function(values) {
							frappe.call({
								method: 'proc_portal.api.contracts.renew_contract',
								args: {
									contract_name: frm.doc.name,
									new_start_date: values.new_start_date,
									new_end_date: values.new_end_date,
									new_value: values.new_value,
								},
								freeze: true,
								freeze_message: __('Creating renewal...'),
								callback: function(r) {
									if (r.message && r.message.name) {
										dialog.hide();
										frappe.set_route('Form', 'Contract', r.message.name);
									}
								}
							});
						}
					});
					dialog.show();
				}, __('Actions'));
			}
		});

		// Terminate - Approved only (not gated by the renewal timing window,
		// termination is available any time the contract is Approved)
		if (frm.doc.workflow_state === 'Approved') {
			frm.add_custom_button(__('Terminate Contract'), function() {
				const dialog = new frappe.ui.Dialog({
					title: __('Terminate Contract'),
					fields: [
						{fieldname: 'reason', label: __('Termination Reason'), fieldtype: 'Small Text', reqd: 1,
							description: __('Breach, mutual termination, supplier failure, etc. This cannot be undone.')},
					],
					primary_action_label: __('Terminate'),
					primary_action: function(values) {
						frappe.call({
							method: 'proc_portal.api.contracts.terminate_contract',
							args: {
								name: frm.doc.name,
								reason: values.reason,
							},
							freeze: true,
							freeze_message: __('Terminating...'),
							callback: function(r) {
								if (r.message && r.message.success) {
									dialog.hide();
									frm.reload_doc();
								}
							}
						});
					}
				});
				dialog.show();
			}, __('Actions'));
		}

		// Link Purchase Orders / Invoices - multi-select linking from the
		// contract side, reusing the same portal APIs (no duplicated logic)
		if (frm.doc.workflow_state === 'Approved') {
			frm.add_custom_button(__('Link Purchase Orders / Invoices'), function() {
				frappe.call({
					method: 'proc_portal.api.contracts.get_linkable_documents',
					args: { contract_name: frm.doc.name },
					callback: function(r) {
						if (!r.message) return;
						const pos = (r.message.purchase_orders || []).map(p => ({ label: `${p.name} — ${format_currency(p.grand_total)} (${p.transaction_date})`, value: `Purchase Order::${p.name}` }));
						const pis = (r.message.purchase_invoices || []).map(p => ({ label: `${p.name} — ${format_currency(p.grand_total)} (${p.posting_date})`, value: `Purchase Invoice::${p.name}` }));
						const all = pos.concat(pis);

						if (!all.length) {
							frappe.msgprint(__('No unlinked purchase orders or invoices found for this supplier.'));
							return;
						}

						const dialog = new frappe.ui.Dialog({
							title: __('Link Documents to Contract'),
							fields: [{
								fieldname: 'docs', fieldtype: 'MultiSelectPills', label: __('Documents'),
								get_data: function() { return all; }
							}],
							primary_action_label: __('Link'),
							primary_action: function(values) {
								const selected = (values.docs || []).map(v => {
									const [doctype, name] = v.split('::');
									return { doctype, name };
								});
								if (!selected.length) return;
								frappe.call({
									method: 'proc_portal.api.contracts.link_documents_to_contract',
									args: { contract_name: frm.doc.name, documents: selected },
									freeze: true,
									callback: function(res) {
										dialog.hide();
										const m = res.message || {};
										let msg = __('Linked {0} document(s).', [(m.linked || []).length]);
										if ((m.failed || []).length) {
											msg += '<br>' + __('Failed: ') + m.failed.map(f => `${f.name} (${f.error})`).join('<br>');
										}
										frappe.msgprint(msg);
										frm.reload_doc();
									}
								});
							}
						});
						dialog.show();
					}
				});
			}, __('Actions'));
		}

		// Termination details - show prominently once terminated
		if (frm.doc.workflow_state === 'Terminated') {
			frm.dashboard.add_indicator(__('Terminated on {0}', [frm.doc.termination_date]), 'red');
			frm.dashboard.add_comment(__('Terminated by {0}: {1}', [frm.doc.terminated_by, frm.doc.termination_reason]), 'red', true);
		}

		// Renewal lineage - show where this contract came from
		if (frm.doc.renewed_from) {
			frm.dashboard.add_comment(__('Renewed from {0}', [
				`<a href="/app/contract/${frm.doc.renewed_from}">${frm.doc.renewed_from}</a>`
			]), 'blue', true);
		}
	}
});

frappe.ui.form.on('Material Request', {
	onload: function(frm) {
		// Mirrors set_warehouse/set_from_warehouse's own company-scoping filter on
		// this same doctype (material_request.js) -- a group Cost Center can't be
		// budgeted against, and another company's is invalid here.
		frm.set_query('set_cost_center', function(doc) {
			return {
				filters: {
					company: doc.company,
					is_group: 0,
				},
			};
		});
	},
	refresh: function(frm) {
		render_budget_preview(frm);
	},
	set_cost_center: function(frm) {
		// Yasser's explicit choice: overwrite every row unconditionally when this
		// field CHANGES, mirroring ERPNext's own autofill_warehouse() exactly
		// (erpnext/public/js/controllers/transaction.js) -- no blank-check, every
		// row gets clobbered to the new value the instant the header field changes.
		// This is a deliberate reversal of the earlier fill-blanks-only decision
		// (PROC_APP_SPEC.md v1.78): the "don't lose a per-row edit" requirement is
		// now met a different way -- this trigger only fires on an actual CHANGE
		// to set_cost_center, not on every save, so an edit made to one row after
		// this fires is never touched again unless the header field changes once
		// more. The corresponding before_validate hook (propagate_cost_center)
		// mirrors this same "on genuine change only" condition server-side.
		if (!frm.doc.set_cost_center) return;
		(frm.doc.items || []).forEach(function(item) {
			frappe.model.set_value(item.doctype, item.name, 'cost_center', frm.doc.set_cost_center);
		});
		render_budget_preview(frm);
	}
});

frappe.ui.form.on('Material Request Item', {
	// Matches ERPNext's own items_add handler for set_warehouse (transaction.js)
	// exactly: a newly added row with no cost center of its own picks up the
	// header default -- unaffected by the change above, still fill-blanks-only,
	// matching the native behavior for a freshly-added row.
	items_add: function(frm, cdt, cdn) {
		var item = frappe.get_doc(cdt, cdn);
		if (!item.cost_center && frm.doc.set_cost_center) {
			item.cost_center = frm.doc.set_cost_center;
		}
		render_budget_preview(frm);
	},
	item_code: function(frm) { render_budget_preview(frm); },
	qty: function(frm) { render_budget_preview(frm); },
	cost_center: function(frm) { render_budget_preview(frm); },
	items_remove: function(frm) { render_budget_preview(frm); },
});

// Live budget-availability panel -- reuses proc_app's get_budget_preview()
// (which itself reuses ERPNext's own BudgetValidation), same figures real
// enforcement uses, matching the portal's own New Request panel exactly.
// Renders into the budget_preview_html Custom Field, now on its own "Budget
// Impact" tab (budget_tab) rather than the Details tab -- with several items
// resolving to different cost center/account pairs the breakdown got long
// enough to push the Items table off-screen. Debounced: fires on every
// item/qty/cost-center change, so this avoids a request per keystroke.
function render_budget_preview(frm) {
	var $wrapper = frm.get_field('budget_preview_html').$wrapper;

	if (!frm.doc.company) {
		$wrapper.html('');
		update_budget_tab_badge(frm, false);
		return;
	}
	var items = (frm.doc.items || [])
		.filter(function(i) { return i.item_code && i.qty; })
		.map(function(i) { return { item_code: i.item_code, qty: i.qty }; });

	clearTimeout(frm._budget_preview_timer);
	if (!items.length) {
		// Clears any stale content from a previous state -- never leaves a
		// panel showing figures for item rows that no longer exist.
		$wrapper.html('');
		update_budget_tab_badge(frm, false);
		return;
	}
	frm._budget_preview_timer = setTimeout(function() {
		frappe.call({
			method: 'proc_app.api.budget.get_budget_preview',
			args: {
				company: frm.doc.company,
				items: JSON.stringify(items),
				cost_center: frm.doc.set_cost_center,
			},
			callback: function(r) {
				var data = r.message || [];
				$wrapper.html(build_budget_preview_html(data));
				var has_breach = data.some(function(b) { return b.status === 'warning' || b.status === 'exceeded'; });
				update_budget_tab_badge(frm, has_breach);
			}
		});
	}, 400);
}

// The panel moving to its own tab means a breach is no longer visible unless
// the user actually clicks that tab -- partly undoing the whole point of a
// LIVE preview. Neither of Frappe's two built-in indicator mechanisms
// actually solves this: frm.dashboard.add_indicator() renders inside the
// same dashboard area that's anchored to whichever tab has show_dashboard:1
// (Connections here, not Budget Impact -- see the earlier tab-placement
// investigation), and frm.page.set_indicator() is a single-slot mechanism
// already owned by the core toolbar for the document's own status badge
// (frappe/public/js/frappe/form/toolbar.js) -- reusing it would clobber that,
// not add to it. Instead: a small coloured dot appended directly onto the
// tab's own clickable button, found via Frappe's own (undocumented but
// predictable) DOM id convention for tab links (form/tab.js's make():
// `${frappe.scrub(doctype,'-')}-${fieldname}-tab`). Wrapped defensively --
// if this internal convention ever changes in a future Frappe version, this
// fails silently rather than breaking the rest of the form's scripts.
function update_budget_tab_badge(frm, has_breach) {
	try {
		var tab_id = frappe.scrub(frm.doctype, '-') + '-budget_tab-tab';
		var $btn = frm.page.wrapper.find('#' + tab_id);
		if (!$btn.length) return;
		$btn.find('.budget-tab-badge').remove();
		if (has_breach) {
			$btn.append(
				'<span class="budget-tab-badge" title="' + __('Over budget') + '" ' +
				'style="display:inline-block; width:8px; height:8px; border-radius:50%; ' +
				'background:#c62828; margin-left:6px; vertical-align:middle;"></span>'
			);
		}
	} catch (e) { /* internal Frappe DOM structure -- fail silently, never break the form */ }
}

function build_budget_preview_html(data) {
	if (!data.length) return '';
	// remaining_after (not remaining_before) drives colour -- that's the figure
	// that actually determines whether a real submit gets Warned/Stopped, so
	// showing green off remaining_before would be exactly the misleading
	// failure mode this panel exists to avoid.
	var colors = { ok: '#2e7d32', warning: '#e0942e', exceeded: '#c62828' };
	return data.map(function(b) {
		if (b.status === 'no_budget') {
			return '<div style="padding:8px 0; color:var(--text-muted);">' + frappe.utils.escape_html(b.message) + '</div>';
		}
		var color = colors[b.status] || '#666';
		function row(label, value) {
			return '<div style="display:flex; justify-content:space-between; padding:2px 0;">' +
				'<span>' + label + '</span><span>' + format_currency(value) + '</span></div>';
		}
		return (
			'<div style="padding:10px 0; border-bottom:1px solid var(--border-color); font-size:13px;">' +
				'<div style="font-weight:600; margin-bottom:6px;">' +
					frappe.utils.escape_html(b.cost_center) + ' \u00b7 ' + frappe.utils.escape_html(b.account) +
				'</div>' +
				row(__('Budget allocated'), b.budget_amount) +
				row(__('Spent (actual)'), b.actual_expense) +
				row(__('Committed (POs)'), b.ordered_amount) +
				row(__('Requested (submitted)'), b.requested_amount) +
				'<div style="border-top:1px solid var(--border-color); margin:4px 0;"></div>' +
				row(__('Available'), b.remaining_before) +
				row(__('This request'), b.this_request_amount) +
				'<div style="border-top:1px solid var(--border-color); margin:4px 0;"></div>' +
				'<div style="display:flex; justify-content:space-between; font-weight:600; color:' + color + ';">' +
					'<span>' + __('Remaining after') + '</span><span>' + format_currency(b.remaining_after) + '</span>' +
				'</div>' +
			'</div>'
		);
	}).join('');
}

frappe.ui.form.on('Material Request', {
	onload: function(frm) {
		// Filtering prevents an invalid choice from being made in the first place;
		// server-side validation (proc_app.material_request_hooks.validate_department_company,
		// before_validate) is the real enforcement -- this is UI convenience only,
		// same relationship as the New Request portal form's own client-side filter
		// (new.html's filteredRequestingDepartments/filteredDepartments getters) to
		// its own server-side check in create_request(). A department whose own
		// company doesn't match this document's company would otherwise later break
		// the Forward-to-Purchase spawn (see material_request_hooks.py).
		var department_filter = function(doc) {
			return {
				filters: {
					company: doc.company,
					is_group: 0,
				},
			};
		};
		frm.set_query('requesting_department', department_filter);
		frm.set_query('concerned_department', department_filter);
	}
});
